  // "Rainbow pattern fascinates a maximum of 24 HD of creatures"
  "rainbow pattern": { pool: "24", sighted: true, effect: { conditions: [["fascinated", null]], marker: true, note: "while you concentrate, and 1 round per level after" } },
  // "Calcific Touch ... 1d4 points of Dexterity damage and slows the target (as the spell) for 1 round. A successful
  // Fortitude save negates the slow effect but not the ability damage"
  "calcific touch": { effect: { abilityDamage: { dex: "1d4" }, conditions: [["staggered", "1"]], note: "slowed (as the spell) for 1 round; at 0 Dexterity it's petrified" }, onSave: { abilityDamage: { dex: "1d4" } } },
  "pain strike, mass": { living: true, effect: { conditions: [["sickened", "min(@cl, 10)"]], marker: true, note: "1d6 nonlethal damage each round; the caster has +4 on Intimidate against it" } },
