  rebuke: { effect: { conditions: [["staggered", "1"]] } },
  "resounding blow": { self: true, effect: { marker: true, note: "melee hits deal +1d6 sonic; staggered 1 round against the target of your judgment or smite (Fortitude negates)" } },
