  "dread bolt": { align: { kind: "bolt", foe: "good", self: "evil", dice: { base: "(min(floor(@cl / 2), 5))d8", outsider: "(min(@cl, 10))d6" }, effect: { conditions: [["sickened", "1"]] } }, touchAttack: "ranged" },
